import{_ as a,c as t,b as s,a0 as o}from"./chunks/framework.DZ_FiXNr.js";const r="/images/analytics_op3.webp",m=JSON.parse('{"title":"OP3 download data","description":"OP3 is an independent download measurement service. When your podcast feed uses its prefix, PodSEO displays the available public OP3 measurements in Analytics → Tracker. This is different from the keyword Tracker under Search Visibility.","frontmatter":{},"headers":[],"relativePath":"features/op3-analytics.md","filePath":"features/op3-analytics.md"}'),n={name:"features/op3-analytics.md"};function i(d,e,l,h,p,c){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="op3-download-data" tabindex="-1">OP3 download data <a class="header-anchor" href="#op3-download-data" aria-label="Permalink to &quot;OP3 download data&quot;">​</a></h1><p>OP3 is an independent download measurement service. When your podcast feed uses its prefix, PodSEO displays the available public OP3 measurements in <strong>Analytics → Tracker</strong>. This is different from the keyword <strong>Tracker</strong> under Search Visibility.</p><p>There is no private account connection to authorize in PodSEO. The <strong>Tracker</strong> source appears when the feed has an active OP3 report; it is not shown for every podcast. OP3 data is public, unlike <a href="/features/hopr-fm-analytics.html">hopr.fm reports</a>.</p><p><a href="/images/analytics_op3.webp" title="Open screenshot at full size"><img src="'+r+'" alt="OP3 Tracker with latest, typical and best episode measurements"></a></p><h2 id="compare-launches-at-the-same-age" tabindex="-1">Compare launches at the same age <a class="header-anchor" href="#compare-launches-at-the-same-age" aria-label="Permalink to &quot;Compare launches at the same age&quot;">​</a></h2><p>The <strong>1 day</strong>, <strong>7 days</strong> and <strong>30 days</strong> columns describe downloads after each episode&#39;s release, rather than downloads in one shared calendar period. Use the same column to compare complete launches.</p><ul><li><strong>Latest episode</strong> shows its first week when complete, or a labelled running total for a newer episode where available.</li><li><strong>Typical episode</strong> uses the median first-week performance of the recent complete episodes shown by the report. Its comparison, when available, is against the preceding group.</li><li><strong>Best episode</strong> shows the highest complete first-week count among the available episodes. Read the label to see how many episodes are included.</li></ul><p>Click a column heading to sort episodes by release order or by its first-day, first-week or first-month count. On mobile, use <strong>Sort episodes</strong>. Sorting rearranges the available rows; it does not fetch a longer history.</p><h2 id="understand-–-and-the-history-window" tabindex="-1">Understand “–” and the history window <a class="header-anchor" href="#understand-–-and-the-history-window" aria-label="Permalink to &quot;Understand “–” and the history window&quot;">​</a></h2><p>OP3 provides about 60 days of download history. A launch count stays “–” when an episode is too young to complete that interval, was published before OP3&#39;s observed coverage, or has no complete count available. The update also needs time to include the completed interval. “–” is not zero and is not a partial count presented as a full launch.</p><p>An older episode can therefore have fewer available columns than a newer one. Do not assume that adding the prefix today recovers earlier downloads. Check the <strong>Updated</strong> date and compare only available, complete measurements.</p><h2 id="listening-apps-versus-episode-counts" tabindex="-1">Listening apps versus episode counts <a class="header-anchor" href="#listening-apps-versus-episode-counts" aria-label="Permalink to &quot;Listening apps versus episode counts&quot;">​</a></h2><p>The <strong>downloads from listening apps since …</strong> line excludes web browsers. The per-episode counts include browser downloads, which can contain automated requests. These two figures also have their own windows; they are not expected to add up or match.</p><p>PodSEO&#39;s OP3 page is a launch comparison table. It does not offer the same daily request investigation, exclusion controls or private audience reports as hopr.fm. For those reports, see <a href="/features/hopr-fm-analytics.html">hopr.fm analytics</a>.</p><h2 id="if-the-tracker-tab-is-missing" tabindex="-1">If the Tracker tab is missing <a class="header-anchor" href="#if-the-tracker-tab-is-missing" aria-label="Permalink to &quot;If the Tracker tab is missing&quot;">​</a></h2><p>Check that your host publishes the OP3 prefix in the feed&#39;s episode links and that OP3 has started reporting downloads. A prefix added only to future episodes will not give complete earlier launches. PodSEO detects supported prefix data from the feed; there is no <strong>Connect OP3</strong> sign-in button.</p><p>Removing the prefix in your host stops routing future requests through OP3. It does not make previously public OP3 data private. For the other available measurements, see <a href="/features/analytics.html">Analytics</a> and <a href="/features/hosting-analytics.html">Hosting platform analytics</a>.</p>',17)])])}const f=a(n,[["render",i]]);export{m as __pageData,f as default};
